/**
 * key-person-risk.ts — 关键人才风险预警
 *
 * 对标 Claw-Code recovery_recipes.rs 的场景化故障建模：
 *   - 单点故障识别 (SPOF: Single Point of Failure)
 *   - 离职影响评估
 *   - 知识继承度评分
 *   - 风险优先级排序
 *
 * 风险维度：
 *   - busFactor: 知识被几人掌握（1=只有本人，越高越安全）
 *   - roleScarcity: 角色在市场/组织内的稀缺程度
 *   - dependencyCount: 多少其他角色依赖此人
 *   - criticalKnowledge: 掌握的关键知识占比
 *   - departureImpact: 离职后的恢复时间估计（天）
 */
/** 角色依赖关系 */
export interface RoleDependency {
    /** 被依赖的角色 ID */
    dependedRoleId: string;
    /** 依赖该角色的其他角色 ID 列表 */
    dependentRoles: string[];
    /** 依赖类型 */
    dependencyType: 'knowledge' | 'approval' | 'execution' | 'coordination';
    /** 是否有替代人选 */
    hasAlternative: boolean;
}
/** 知识领域 */
export interface KnowledgeDomain {
    name: string;
    /** 掌握该知识的角色 ID 列表 */
    heldByRoles: string[];
    /** 关键程度 0-1 */
    criticality: number;
}
/** 角色风险画像 */
export interface RoleRiskProfile {
    roleId: string;
    roleName: string;
    /** Bus Factor: 掌握关键知识的人数（含本人） */
    busFactor: number;
    /** 角色稀缺度 0-1（1=极度稀缺） */
    roleScarcity: number;
    /** 依赖此角色的其他角色数 */
    dependencyCount: number;
    /** 掌握的关键知识域列表 */
    criticalKnowledgeDomains: string[];
    /** 综合风险评分 0-1 */
    overallRiskScore: number;
    /** 离职影响：恢复时间估计（天） */
    estimatedRecoveryDays: number;
    /** 风险等级 */
    riskLevel: 'critical' | 'high' | 'medium' | 'low';
}
/** 团队风险汇总 */
export interface KeyPersonRiskReport {
    teamId: string;
    profiles: RoleRiskProfile[];
    /** 最高单点风险的三个角色 */
    topSpofRisks: RoleRiskProfile[];
    /** 团队平均 Bus Factor */
    averageBusFactor: number;
    /** 有多少个角色 busFactor <= 1 */
    singlePointCount: number;
    /** 关键知识域未覆盖数 */
    uncoveredDomains: string[];
    generatedAt: string;
}
export declare function analyzeKeyPersonRisk(params: {
    teamId: string;
    dependencies: RoleDependency[];
    knowledgeDomains: KnowledgeDomain[];
    roleScarcityMap: Record<string, number>;
    roleNames: Record<string, string>;
}): KeyPersonRiskReport;
/** 从简易角色列表构造依赖关系（假设所有角色互相依赖） */
export declare function buildDependenciesFromRoles(roleIds: string[], dependencyType?: RoleDependency['dependencyType']): RoleDependency[];
/** 从简易角色-知识映射构造知识域 */
export declare function buildKnowledgeDomains(roleKnowledgeMap: Record<string, string[]>, domainCriticality?: Record<string, number>): KnowledgeDomain[];
